9|// Paths the size check skips. Entries ending in "/" match that directory
10|// anywhere in the path. Entries with "*" match the file name. Other entries
11|// match the full path or the file name. Add a pattern here (and say why in
12|// the commit message) when a file really is generated or third-party.
13|export const IGNORE_PATTERNS = [
14|  // Lockfiles: not authored by agents.
15|  'package-lock.json',
16|  'pnpm-lock.yaml',
17|  'yarn.lock',
18|  'bun.lockb',
19|  'uv.lock',
20|  'poetry.lock',
21|  '*.lock',
22|  // Codegen: generated dirs cover their *.d.ts files too.
23|  '*.generated.*',
24|  '*.gen.*',
25|  'next-env.d.ts',
26|  'generated/',
27|  '__generated__/',
28|  // Build output.
29|  '.next/',
30|  'dist/',
31|  'out/',
32|  'coverage/',
33|  // Processed book data, and all of public/.
34|  'public/',
35|  'data/processed/',
36|  'pipeline/out/',
37|  // Agent and session logs (the project log dir is agent-logs/).
38|  'agent-logs/',
39|  // Vendored third-party skills.
40|  '.agents/skills/',
41|];
42|
43|function globToRegExp(glob) {
44|  return new RegExp('^' + glob.split('*').map(escapeRegExp).join('.*') + '$');
45|}
46|
47|function escapeRegExp(text) {
48|  return text.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
49|}
50|
51|function basename(path) {
52|  const index = path.lastIndexOf('/');
53|  return index === -1 ? path : path.slice(index + 1);
54|}
55|
56|export function isIgnored(path) {
57|  const name = basename(path);
58|  for (const pattern of IGNORE_PATTERNS) {
59|    if (pattern.endsWith('/')) {
60|      if (path === pattern.slice(0, -1) || path.startsWith(pattern) || path.includes('/' + pattern)) {
61|        return true;
62|      }
63|    } else if (pattern.includes('*')) {
64|      if (globToRegExp(pattern).test(name)) return true;
65|    } else if (path === pattern || name === pattern || path.endsWith('/' + pattern)) {
66|      return true;
67|    }
68|  }
69|  return false;
70|}
71|
72|export function estimateTokens(bytes) {
73|  return Math.ceil(bytes / BYTES_PER_TOKEN);
74|}
75|
76|// Pure and testable: entries look like { path, bytes, isBinary }.
77|export function findOversized(entries) {
78|  const oversized = [];
79|  for (const entry of entries) {
80|    if (entry.isBinary || isIgnored(entry.path)) continue;
81|    const tokens = estimateTokens(entry.bytes);
82|    if (tokens > MAX_TOKENS) oversized.push({ path: entry.path, bytes: entry.bytes, tokens });
83|  }
84|  return oversized;
85|}
86|
87|export const SPLIT_HELP = `How to split it:
88|- Split by responsibility into small modules, one concern per file, roughly under 300 lines.
89|- Put shared types in their own file.
90|- Move fixtures and test data to fixtures/ or public/.
91|- For TS/JS create a folder with an index.ts that re-exports the pieces so imports stay stable.
92|- For docs split by heading into docs/<topic>/*.md with a short index.
93|- For tests split per behavior.
94|- Never minify or remove comments to sneak under the limit.
95|- If the file really is generated or third-party, add its pattern to the ignore list in this script and explain why in the commit message.`;
96|
97|function stagedPaths() {
98|  const output = execFileSync(
99|    'git',
100|    ['diff', '--cached', '--name-only', '--diff-filter=ACMR', '-z'],
101|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
102|  );
103|  const text = output.toString('utf8');
104|  return text.length === 0 ? [] : text.split('\0').filter((entry) => entry !== '');
105|}
106|
107|// Pure and testable: flags from `git diff --numstat -z` output. Each record is
108|// one NUL-terminated "added\tdeleted\tpath" chunk; a rename is a chunk with
109|// an empty path followed by old-name and new-name chunks, keyed on the new.
110|export function parseNumstatZ(text) {
111|  const flags = new Map();
112|  if (text.length === 0) return flags;
113|  const parts = text.split('\0');
114|  for (let i = 0; i < parts.length; i++) {
115|    const chunk = parts[i];
116|    if (chunk === '') continue;
117|    const record = /^(\d+|-)\t(\d+|-)\t([\s\S]*)$/.exec(chunk);
118|    if (!record) continue;
119|    const isBinary = record[1] === '-' && record[2] === '-';
120|    let path = record[3];
121|    if (path === '') {
122|      const renamed = parts[i + 2];
123|      i += 2;
124|      if (renamed === undefined || renamed === '') continue;
125|      path = renamed;
126|    }
127|    flags.set(path, isBinary);
128|  }
129|  return flags;
130|}
131|
132|// Binary flags from git's own numstat: git prints "-\t-\t" for files whose
133|// first 8000 bytes hold a NUL byte, so this reuses that detection.
134|function stagedBinaryFlags() {
135|  const output = execFileSync(
136|    'git',
137|    ['diff', '--cached', '--numstat', '--diff-filter=ACMR', '-z'],
138|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
139|  );
140|  return parseNumstatZ(output.toString('utf8'));
141|}
142|
143|function stagedBlobSize(path) {
144|  const output = execFileSync('git', ['cat-file', '-s', ':' + path], {
145|    encoding: 'utf8',
146|    stdio: ['ignore', 'pipe', 'ignore'],
147|  });
148|  return Number.parseInt(output.trim(), 10);
149|}
150|
151|function main() {
152|  let paths;
153|  let binaryFlags = new Map();
154|  try {
155|    paths = stagedPaths();
156|    binaryFlags = stagedBinaryFlags();
157|  } catch {
158|    console.error('warning: not a git repo, skipping the file-size check');
159|    return 0;
160|  }
161|  const entries = [];
162|  for (const path of paths) {
163|    if (isIgnored(path)) continue;
164|    let bytes;
165|    try {
166|      bytes = stagedBlobSize(path);
167|    } catch {
168|      continue; // Left the index since the diff was read.
169|    }
170|    entries.push({ path, bytes, isBinary: binaryFlags.get(path) === true });
171|  }
172|  const oversized = findOversized(entries);
173|  if (oversized.length === 0) return 0;
174|  console.error(`error: ${oversized.length} staged file(s) over the ${MAX_TOKENS}-token limit (tokens = ceil(bytes/4)):`);
175|  for (const file of oversized) {
176|    console.error(`  ${file.path}: ${file.bytes} bytes, about ${file.tokens} tokens`);
177|  }
178|  console.error('');
179|  console.error(SPLIT_HELP);
180|  return 1;
181|}
182|
183|const invokedAsScript = process.argv[1] === fileURLToPath(import.meta.url);
