1|import test from 'node:test';
2|import assert from 'node:assert/strict';
3|import { estimateTokens, findOversized, isIgnored, MAX_TOKENS, parseNumstatZ } from './check-file-size.mjs';
4|
5|const OVER = (MAX_TOKENS + 1) * 4; // 20004 bytes, just over the limit
6|const HUGE = 10 * 1024 * 1024;
7|
8|test('tokens are ceil(bytes/4)', () => {
9|  assert.equal(estimateTokens(20000), 5000);
10|  assert.equal(estimateTokens(20001), 5001);
11|  assert.equal(estimateTokens(0), 0);
12|});
13|
14|test('an oversized file fails', () => {
15|  const found = findOversized([{ path: 'src/big.js', bytes: OVER, isBinary: false }]);
16|  assert.equal(found.length, 1);
17|  assert.equal(found[0].path, 'src/big.js');
18|  assert.equal(found[0].tokens, 5001);
19|});
20|
21|test('a file with exactly 5000 tokens passes', () => {
22|  const found = findOversized([{ path: 'src/edge.js', bytes: 20000, isBinary: false }]);
23|  assert.deepEqual(found, []);
24|});
25|
26|test('a file with 5001 tokens fails', () => {
27|  const found = findOversized([{ path: 'src/over.js', bytes: 20001, isBinary: false }]);
28|  assert.equal(found.length, 1);
29|});
30|
31|test('a small file passes', () => {
32|  const found = findOversized([{ path: 'src/small.js', bytes: 120, isBinary: false }]);
33|  assert.deepEqual(found, []);
34|});
35|
36|test('ignored paths pass even when huge', () => {
37|  const paths = [
38|    'package-lock.json',
39|    'pnpm-lock.yaml',
40|    'yarn.lock',
41|    'bun.lockb',
42|    'uv.lock',
43|    'poetry.lock',
44|    'sub/dir/odd.lock',
45|    'src/types.generated.ts',
46|    'src/query.gen.js',
47|    'next-env.d.ts',
48|    'generated/schema.d.ts',
49|    'src/__generated__/relay.ts',
50|    '.next/static/chunks/app.js',
51|    'dist/bundle.js',
52|    'out/index.html',
53|    'coverage/lcov.info',
54|    'public/books/oz.json',
55|    'public/favicon.ico',
56|    'data/processed/scenes.json',
57|    'pipeline/out/music.json',
58|    'agent-logs/01-plan.jsonl',
59|    '.agents/skills/unslop/SKILL.md',
60|  ];
61|  for (const path of paths) assert.equal(isIgnored(path), true, `${path} should be ignored`);
62|  const entries = paths.map((path) => ({ path, bytes: HUGE, isBinary: false }));
63|  assert.deepEqual(findOversized(entries), []);
64|});
65|
66|test('non-ignored paths are not ignored', () => {
67|  for (const path of ['src/app.ts', 'scripts/check-size.mjs', 'README.md', 'data/raw/oz.epub', 'docs/muse-code-sessions/01.md']) {
68|    assert.equal(isIgnored(path), false, `${path} should be checked`);
69|  }
70|});
71|
72|test('binary files pass even when huge', () => {
73|  const found = findOversized([{ path: 'assets/cover.png', bytes: HUGE, isBinary: true }]);
74|  assert.deepEqual(found, []);
75|});
76|
77|test('numstat -z parser flags binary, renames, and spaced paths', () => {
78|  const raw =
79|    '-\t-\tassets/cover.png\0' + '3\t1\tmy file.txt\0' + '5\t2\t\0old.txt\0new.txt\0' + '1\t0\tsrc/ok.js\0';
80|  const flags = parseNumstatZ(raw);
81|  assert.equal(flags.get('assets/cover.png'), true);
82|  assert.equal(flags.get('my file.txt'), false);
83|  assert.equal(flags.get('new.txt'), false);
84|  assert.equal(flags.has('old.txt'), false);
85|  assert.equal(flags.get('src/ok.js'), false);
86|});
87|
88|test('numstat -z parser handles empty output', () => {
89|  assert.equal(parseNumstatZ('').size, 0);
90|});
91|
92|test('only the offending files are reported', () => {
93|  const found = findOversized([
94|    { path: 'src/ok.js', bytes: 100, isBinary: false },
95|    { path: 'src/bad.js', bytes: OVER, isBinary: false },
96|    { path: 'dist/skipped.js', bytes: HUGE, isBinary: false },
97|  ]);
98|  assert.deepEqual(
99|    found.map((entry) => entry.path),
100|    ['src/bad.js'],
101|  );
102|});

